declare(strict_types=1);
require_once __DIR__.'/TestShop.php';
use PHPUnit\Framework\TestCase;
use Sexogate\{Config,Payments,RuleViolation};
use Sexogate\Providers\StripeProvider;
final class StripeTestHttp implements Stripe\HttpClient\ClientInterface
{
    public array $responses=[];public array $requests=[];
    public function request($method,$absUrl,$headers,$params,$hasFile,$apiMode='v1',$maxNetworkRetries=null)
    {$this->requests[]=compact('method','absUrl','headers','params');$r=array_shift($this->responses);if($r instanceof Throwable)throw $r;if(!is_array($r))throw new RuntimeException('UNPLANNED_HTTP_REQUEST');return [json_encode($r,JSON_THROW_ON_ERROR),200,[]];}
}
final class StripeTest extends TestCase
{
    private function config(TestShop $s):Config
    {$v=[];foreach(['env','secret','base_path','app_url','db_dsn','db_user','db_password'] as $k)$v[$k]=$s->f->config->get($k);return new Config($v+['payment_provider'=>'stripe','stripe_secret_key'=>'sk_test_fixture_private_http_only','stripe_webhook_secret'=>'whsec_fixture_private_http_only','stripe_business_approved'=>true,'stripe_enabled_currencies'=>'TRY']);}
    private function signed(array $event):array{$raw=json_encode($event,JSON_THROW_ON_ERROR);$t=time();return [$raw,'t='.$t.',v1='.hash_hmac('sha256',$t.'.'.$raw,'whsec_fixture_private_http_only')];}
    protected function tearDown():void{Stripe\ApiRequestor::setHttpClient(new Stripe\HttpClient\CurlClient());}
    public function testSdkCreatesPrivateServerAmountAndUsesStableIdempotency():void
    {$s=new TestShop(1,false);self::assertTrue(class_exists(StripeProvider::class),'Stripe PHP adaptörü eksik.');$h=new StripeTestHttp();Stripe\ApiRequestor::setHttpClient($h);$h->responses[]=['id'=>'cs_test_fixture','object'=>'checkout.session','url'=>'https://checkout.stripe.com/c/pay/cs_test_fixture','amount_total'=>15400,'currency'=>'try','metadata'=>['orderId'=>$s->order['orderId']],'payment_status'=>'unpaid','status'=>'open','payment_intent'=>'pi_fixture'];$p=new StripeProvider($this->config($s));$result=$p->createSession(['id'=>$s->order['orderId'],'number'=>'SG-1','totalMinor'=>15400,'currency'=>'TRY'],'http://127.0.0.1:3183/test/siparis/one','http://127.0.0.1:3183/test/sepet','session-stable-12345678');self::assertSame('cs_test_fixture',$result['id']);self::assertSame(15400,$h->requests[0]['params']['line_items'][0]['price_data']['unit_amount']);self::assertStringNotContainsString('Saten',json_encode($h->requests[0]['params']));self::assertTrue((bool)array_filter($h->requests[0]['headers'],fn($x)=>str_contains($x,'session-stable-12345678')));}
    public function testSignedWebhookIsDurableAndOnlyOneStockMovementIsCommitted():void
    {$s=new TestShop(1,false);self::assertTrue(class_exists(Payments::class),'Ödeme inbox modülü eksik.');$s->f->db->execute("UPDATE payments SET provider='stripe',provider_reference='cs_test_fixture' WHERE order_id=?",[$s->order['orderId']]);$event=['id'=>'evt_fixture_valid','object'=>'event','type'=>'checkout.session.completed','livemode'=>false,'created'=>time(),'data'=>['object'=>['id'=>'cs_test_fixture','object'=>'checkout.session','amount_total'=>15400,'currency'=>'try','metadata'=>['orderId'=>$s->order['orderId']],'payment_status'=>'paid','status'=>'complete','payment_intent'=>'pi_fixture']]];[$raw,$sig]=$this->signed($event);$p=new Payments($s->f->db,$this->config($s));$first=$p->receive($raw,$sig);self::assertTrue($first['received']);self::assertSame('pending',$s->f->db->one('SELECT status FROM provider_events')['status']);$p->process('evt_fixture_valid');$p->receive($raw,$sig);$p->process('evt_fixture_valid');self::assertSame(1,(int)$s->f->db->one("SELECT COUNT(*) n FROM inventory_movements WHERE type='sale'")['n']);self::assertSame('succeeded',$s->f->db->one('SELECT status FROM payments')['status']);}
    public function testInvalidSignatureNeverCreatesAnInboxJob():void
    {$s=new TestShop();self::assertTrue(class_exists(Payments::class),'Ödeme inbox modülü eksik.');$p=new Payments($s->f->db,$this->config($s));try{$p->receive('{"id":"evt_forged"}','bad');self::fail('İmzasız olay kabul edildi.');}catch(RuleViolation $e){self::assertSame(401,$e->status);}self::assertSame(0,(int)$s->f->db->one('SELECT COUNT(*) n FROM provider_events')['n']);}
    public function testSignedWrongCurrencyDoesNotPayAnOrder():void
    {$s=new TestShop(1,false);self::assertTrue(class_exists(Payments::class),'Ödeme inbox modülü eksik.');$s->f->db->execute("UPDATE payments SET provider='stripe',provider_reference='cs_test_fixture' WHERE order_id=?",[$s->order['orderId']]);[$raw,$sig]=$this->signed(['id'=>'evt_wrong_currency','object'=>'event','type'=>'checkout.session.completed','livemode'=>false,'created'=>time(),'data'=>['object'=>['id'=>'cs_test_fixture','amount_total'=>15400,'currency'=>'usd','metadata'=>['orderId'=>$s->order['orderId']],'payment_status'=>'paid','payment_intent'=>'pi_fixture']]]);$p=new Payments($s->f->db,$this->config($s));try{$p->receive($raw,$sig);$p->process('evt_wrong_currency');self::fail('Yanlış para birimi kabul edildi.');}catch(RuleViolation){}self::assertSame('pending',$s->f->db->one('SELECT status FROM payments')['status']);}
    public function testWorkerActuallyProcessesThePersistedStripeEvent():void
    {$s=new TestShop(1,false);$s->f->db->execute("UPDATE payments SET provider='stripe',provider_reference='cs_test_fixture' WHERE order_id=?",[$s->order['orderId']]);[$raw,$sig]=$this->signed(['id'=>'evt_worker_fixture','object'=>'event','type'=>'checkout.session.completed','livemode'=>false,'created'=>time(),'data'=>['object'=>['id'=>'cs_test_fixture','amount_total'=>15400,'currency'=>'try','metadata'=>['orderId'=>$s->order['orderId']],'payment_status'=>'paid','payment_intent'=>'pi_worker']]]);(new Payments($s->f->db,$this->config($s)))->receive($raw,$sig);$result=(new Sexogate\Worker($s->f->db,$this->config($s)))->tick();self::assertSame('succeeded',$s->f->db->one('SELECT status FROM payments')['status']);self::assertSame(1,$result['completed']);}
    public function testReconciliationKeepsThePaymentIntentForFutureRefunds():void
    {$s=new TestShop(1,false);$s->f->db->execute("UPDATE payments SET provider='stripe',provider_reference='cs_test_fixture' WHERE order_id=?",[$s->order['orderId']]);$h=new StripeTestHttp();Stripe\ApiRequestor::setHttpClient($h);$h->responses[]=['id'=>'cs_test_fixture','object'=>'checkout.session','amount_total'=>15400,'currency'=>'try','metadata'=>['orderId'=>$s->order['orderId']],'payment_status'=>'paid','status'=>'complete','payment_intent'=>'pi_reconciled'];(new Payments($s->f->db,$this->config($s)))->reconcile();$p=$s->f->db->one('SELECT status,payment_intent FROM payments');self::assertSame('succeeded',$p['status']);self::assertSame('pi_reconciled',$p['payment_intent']);}
    public function testOldPendingRefundEventCannotReopenAnAlreadyFailedRefund():void
    {$s=new TestShop(2);$s->f->db->execute("UPDATE payments SET provider='stripe',provider_reference='cs_refund_fixture',payment_intent='pi_refund_fixture'");$config=$this->config($s);$r=new Sexogate\Returns($s->f->db,$config);$one=$r->request($s->order['orderId'],$s->order['trackingToken'],$s->variant,1,'İade banka senaryosu','unopened',bin2hex(random_bytes(16)));$r->decide($one['id'],true,'TEST iade kabul kararı',bin2hex(random_bytes(16)),$s->admin);$r->receive($one['id'],'TEST depo teslim referansı',bin2hex(random_bytes(16)),$s->admin);$r->inspect($one['id'],'quarantine','TEST kalite inceleme kaydı',bin2hex(random_bytes(16)),$s->admin);$refund=$r->refund($one['id'],bin2hex(random_bytes(16)),$s->admin);$h=new StripeTestHttp();Stripe\ApiRequestor::setHttpClient($h);$h->responses[]=['id'=>'re_fixture','object'=>'refund','payment_intent'=>'pi_refund_fixture','amount'=>14900,'currency'=>'try','status'=>'pending'];$p=new Payments($s->f->db,$config);$p->refund($refund['id']);foreach([['failed','evt_refund_failed',time()],['pending','evt_refund_old',time()-60]] as [$status,$eventId,$created]){[$raw,$sig]=$this->signed(['id'=>$eventId,'object'=>'event','type'=>'refund.updated','livemode'=>false,'created'=>$created,'data'=>['object'=>['id'=>'re_fixture','object'=>'refund','payment_intent'=>'pi_refund_fixture','amount'=>14900,'currency'=>'try','status'=>$status]]]);$p->receive($raw,$sig);$p->process($eventId);}self::assertSame('failed',$s->f->db->one('SELECT status FROM refunds')['status']);self::assertSame('refund_failed',$s->f->db->one('SELECT status FROM returns')['status']);self::assertSame(0,(int)$s->f->db->one('SELECT refunded_minor FROM payments')['refunded_minor']);}
    public function testBoundedReconciliationMovesPastOldFailedSessions():void
    {$s=new TestShop(1,false);$orders=[$s->order['orderId']];for($i=0;$i<2;$i++){$token=bin2hex(random_bytes(32));(new Sexogate\Cart($s->f->db,$s->f->config))->set($token,$s->variant,1);$input=['email'=>'reconcile@example.invalid','fullName'=>'Hamza ÖZBALKAN','phone'=>'05000000000','line1'=>'Şişli Çeşme adresi','city'=>'İstanbul','postalCode'=>'34000','privacyAccepted'=>true,'termsAccepted'=>true,'idempotencyKey'=>bin2hex(random_bytes(16))];$c=new Sexogate\Commerce($s->f->db,$s->f->config);$input['quoteToken']=$c->quote($token,$input)['quoteToken'];$orders[]=$c->checkout($token,$input)['orderId'];}$h=new StripeTestHttp();Stripe\ApiRequestor::setHttpClient($h);foreach($orders as $i=>$id){$s->f->db->execute("UPDATE payments SET provider='stripe',provider_reference=? WHERE order_id=?",['cs_reconcile_'.$i,$id]);$s->f->db->execute('UPDATE orders SET created_at=DATE_ADD(DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 DAY),INTERVAL ? MINUTE) WHERE id=?',[$i,$id]);$h->responses[]=['id'=>'cs_reconcile_'.$i,'object'=>'checkout.session','amount_total'=>15400,'currency'=>'try','metadata'=>['orderId'=>$id],'payment_status'=>$i===2?'paid':'unpaid','status'=>$i===2?'complete':'expired','payment_intent'=>'pi_reconcile_'.$i];}$p=new Payments($s->f->db,$this->config($s));self::assertSame(2,$p->reconcile(2)['checked']);self::assertSame('pending',$s->f->db->one('SELECT status FROM payments WHERE order_id=?',[$orders[2]])['status']);$p->reconcile(2);self::assertSame('succeeded',$s->f->db->one('SELECT status FROM payments WHERE order_id=?',[$orders[2]])['status']);}
}
